let schemaReady=null;
/* Adds the payment columns/table to existing databases once per Worker instance. */
function ensureSchema(env){if(!schemaReady)schemaReady=(async()=>{try{await env.DB.prepare("ALTER TABLE orders ADD COLUMN payment_method TEXT NOT NULL DEFAULT ''").run();}catch(e){}await env.DB.prepare('CREATE TABLE IF NOT EXISTS email_log (id TEXT PRIMARY KEY, order_id TEXT NOT NULL DEFAULT \'\', kind TEXT NOT NULL, to_addr TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL DEFAULT \'\', html TEXT NOT NULL DEFAULT \'\', ok INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL)').run();await env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_email_log_order ON email_log(order_id, created_at)').run();await env.DB.prepare('CREATE TABLE IF NOT EXISTS payment_links (id TEXT PRIMARY KEY, order_id TEXT NOT NULL, url TEXT NOT NULL, amount_cents INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT \'\', sent_at TEXT NOT NULL)').run();await env.DB.prepare("CREATE TABLE IF NOT EXISTS discount_rules (id TEXT PRIMARY KEY, label TEXT NOT NULL, scope TEXT NOT NULL DEFAULT 'all', match_value TEXT NOT NULL DEFAULT '', percent REAL NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, starts_at TEXT NOT NULL DEFAULT '', ends_at TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL)").run();await env.DB.prepare("CREATE TABLE IF NOT EXISTS merchants (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, company TEXT NOT NULL DEFAULT '', contact_name TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', password_hash TEXT NOT NULL DEFAULT '', password_salt TEXT NOT NULL DEFAULT '', password_iterations INTEGER NOT NULL DEFAULT 120000, discount_percent REAL NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, last_login_at TEXT NOT NULL DEFAULT '')").run();await env.DB.prepare('CREATE TABLE IF NOT EXISTS merchant_sessions (token_hash TEXT PRIMARY KEY, merchant_id TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL)').run();await env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_merchant_sessions_m ON merchant_sessions(merchant_id)').run();await env.DB.prepare("CREATE TABLE IF NOT EXISTS merchant_rates (id TEXT PRIMARY KEY, merchant_id TEXT NOT NULL, scope TEXT NOT NULL DEFAULT 'vendor', match_value TEXT NOT NULL DEFAULT '', percent REAL NOT NULL DEFAULT 0, created_at TEXT NOT NULL)").run();await env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_merchant_rates_m ON merchant_rates(merchant_id)').run();try{await env.DB.prepare('ALTER TABLE merchants ADD COLUMN bonus_percent REAL NOT NULL DEFAULT 0').run();}catch(e){}for(const col of ["discount_cents INTEGER NOT NULL DEFAULT 0","gross_cents INTEGER NOT NULL DEFAULT 0","discount_json TEXT NOT NULL DEFAULT '[]'","merchant_id TEXT NOT NULL DEFAULT ''","merchant_company TEXT NOT NULL DEFAULT ''","rent_credit_cents INTEGER NOT NULL DEFAULT 0","rent_credit_note TEXT NOT NULL DEFAULT ''","extra_percent REAL NOT NULL DEFAULT 0"]){try{await env.DB.prepare('ALTER TABLE orders ADD COLUMN '+col).run();}catch(e){}}})().catch(e=>{schemaReady=null;throw e;});return schemaReady;}
function validPayUrl(v){try{const u=new URL(v);return u.protocol==='https:'&&!!u.hostname&&v.length<=1000;}catch(e){return false;}}
const now=()=>new Date().toISOString();
const clean=(v,n=500)=>String(v??'').trim().slice(0,n);
const validEmail=v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
const cors={'access-control-allow-origin':'https://aqlx.shop','access-control-allow-methods':'GET, POST, PATCH, DELETE, OPTIONS','access-control-allow-headers':'content-type, authorization','cache-control':'no-store'};
function res(data,status=200){return Response.json(data,{status,headers:cors});}
function itemsOk(raw){if(!Array.isArray(raw)||!raw.length||raw.length>100)return null;const out=[];for(const x of raw){const quantity=Math.floor(Number(x.quantity)),unit_price_cents=Number(x.unit_price_cents);if(!clean(x.title,200)||!Number.isInteger(quantity)||quantity<1||quantity>999||!Number.isInteger(unit_price_cents)||unit_price_cents<0)return null;out.push({product_id:clean(x.product_id,80),variant_id:clean(x.variant_id,80),handle:clean(x.handle,255),title:clean(x.title,200),variant:clean(x.variant,200),sku:clean(x.sku,100),quantity,unit_price_cents,line_total_cents:quantity*unit_price_cents});}return out;}
/* Re-price every line from the live Shopify product JSON so the browser can't set its own prices.
   Blocks $0 items and products tagged detailers-only. If Shopify can't be reached, the line is kept
   with the browser price and the order is flagged for manual checking. */
async function verifyItems(env,items){
 const domain=clean(env.STORE_DOMAIN||'aqlx.shop',100),cache=new Map(),out=[];let unverified=0;
 for(const it of items){
  let product=null,missing=false;
  if(it.handle){
   if(!cache.has(it.handle))cache.set(it.handle,fetch(`https://${domain}/products/${encodeURIComponent(it.handle)}.js`,{headers:{accept:'application/json'},cf:{cacheTtl:60}}).then(async r=>r.ok?{p:await r.json()}:{missing:r.status===404}).catch(()=>({})));
   const got=await cache.get(it.handle);product=got.p||null;missing=!!got.missing;
  }
  if(missing)return{error:`"${it.title}" is no longer available. Please update your cart.`};
  if(!product){unverified++;out.push({...it,_meta:{verified:false}});continue;}
  const v=(product.variants||[]).find(x=>String(x.id)===String(it.variant_id));
  if(!v)return{error:`"${it.title}${it.variant?' — '+it.variant:''}" is no longer available. Please update your cart.`};
  const tags=(Array.isArray(product.tags)?product.tags:String(product.tags||'').split(',')).map(t=>String(t).trim().toLowerCase());
  if(tags.includes('detailers-only'))return{error:`"${it.title}" is for professional detailers only. Please request it through Get Supplied.`};
  const price=Math.round(Number(v.price));
  if(!Number.isInteger(price)||price<=0)return{error:`"${it.title}" doesn't have a price yet. Please message us for a quote.`};
  out.push({...it,title:clean(product.title||it.title,200),unit_price_cents:price,line_total_cents:price*it.quantity,_meta:{verified:true,vendor:String(product.vendor||''),product_type:String(product.type||product.product_type||''),tags,handle:it.handle}});
 }
 return{items:out,unverified};
}
async function authorized(req,env){return !!env.ADMIN_TOKEN&&safeEqual(req.headers.get('authorization')||'',`Bearer ${env.ADMIN_TOKEN}`);}
// Compares without stopping at the first wrong character, so response timing can't leak the token.
function safeEqual(a,b){const x=new TextEncoder().encode(String(a)),y=new TextEncoder().encode(String(b));let d=x.length^y.length;for(let i=0;i<Math.max(x.length,y.length);i++)d|=(x[i]||0)^(y[i]||0);return d===0;}
// Token guessing protection: 10 wrong tokens from one IP in 15 minutes locks that IP out for the rest of the window.
async function authLockedOut(env,ip){await env.DB.prepare('CREATE TABLE IF NOT EXISTS auth_failures (ip TEXT NOT NULL, ts INTEGER NOT NULL)').run();const r=await env.DB.prepare('SELECT COUNT(*) AS n FROM auth_failures WHERE ip=? AND ts>?').bind(ip,Math.floor(Date.now()/1000)-900).first();return Number(r?.n||0)>=10;}
async function recordAuthFailure(env,ip){const now=Math.floor(Date.now()/1000);await env.DB.prepare('INSERT INTO auth_failures(ip,ts) VALUES(?,?)').bind(ip,now).run();await env.DB.prepare('DELETE FROM auth_failures WHERE ts<?').bind(now-86400).run();}
