async function sendGmail(env,to,subject,body,html=null,meta=null){let ok=false;try{ok=await sendGmailRaw(env,to,subject,body,html);return ok;}finally{if(meta&&env.DB){try{await env.DB.prepare('INSERT INTO email_log(id,order_id,kind,to_addr,subject,body,html,ok,created_at) VALUES(?,?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),String(meta.orderId||''),String(meta.kind||'other'),String(to),String(subject),String(body||''),String(html||''),ok?1:0,new Date().toISOString()).run();}catch(e){console.error('Email log failed:',String(e));}}}}
async function shopRecipients(env){const r=await env.DB.prepare('SELECT email FROM notification_emails WHERE enabled=1 ORDER BY email').all();const list=(r.results||[]).map(x=>x.email).filter(validEmail);if(!list.length&&validEmail(env.INITIAL_NOTIFICATION_EMAIL))list.push(env.INITIAL_NOTIFICATION_EMAIL);return list;}
async function sendGmailRaw(env,to,subject,body,html=null){
 if(!env.GMAIL_CLIENT_ID||!env.GMAIL_CLIENT_SECRET||!env.GMAIL_REFRESH_TOKEN||!env.GMAIL_SENDER){console.log('Gmail notification skipped: OAuth settings not configured.');return false;}
 const tr=await fetch('https://oauth2.googleapis.com/token',{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:env.GMAIL_CLIENT_ID,client_secret:env.GMAIL_CLIENT_SECRET,refresh_token:env.GMAIL_REFRESH_TOKEN,grant_type:'refresh_token'})});
 const td=await tr.json();if(!tr.ok||!td.access_token){console.error('Gmail token refresh failed:',JSON.stringify(td));return false;}
 const encode=s=>btoa(unescape(encodeURIComponent(s))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
 const hdr=s=>String(s).replace(/[\r\n]/g,' ').replace(/[^\x20-\x7E]/g,'');
 let raw;
 if(html){const boundary='stoich_'+crypto.randomUUID().replace(/-/g,'');raw=[`To: ${hdr(to)}`,`From: ${hdr(env.GMAIL_SENDER)}`,`Subject: ${hdr(subject)}`,'MIME-Version: 1.0',`Content-Type: multipart/alternative; boundary="${boundary}"`,'',`--${boundary}`,'Content-Type: text/plain; charset=UTF-8','Content-Transfer-Encoding: 8bit','',body,`--${boundary}`,'Content-Type: text/html; charset=UTF-8','Content-Transfer-Encoding: 8bit','',html,`--${boundary}--`].join('\r\n');}
 else raw=[`To: ${hdr(to)}`,`From: ${hdr(env.GMAIL_SENDER)}`,`Subject: ${hdr(subject)}`,'MIME-Version: 1.0','Content-Type: text/plain; charset=UTF-8','',body].join('\r\n');
 const sr=await fetch('https://gmail.googleapis.com/gmail/v1/users/me/messages/send',{method:'POST',headers:{authorization:`Bearer ${td.access_token}`,'content-type':'application/json'},body:JSON.stringify({raw:encode(raw)})});
 if(!sr.ok){console.error('Gmail send failed:',await sr.text());return false;}return true;
}
